const item = $input.first().json;
let telemetry;

if (item.stdout) {
  try {
    telemetry = JSON.parse(item.stdout);
  } catch(e) {
    telemetry = {};
  }
} else if (item.body && item.body.hardware) {
  telemetry = item.body;
} else if (item.hardware) {
  telemetry = item;
} else if (item.body && item.body.simulate) {
  const isSpike = item.body.thermal_spike === true;
  telemetry = {
    node_id: 'sbb-edge-simulated-01',
    timestamp: new Date().toISOString(),
    hardware: {
      cpu_temp_celsius: isSpike ? 85.5 : 48.0,
      cpu_usage_percent: isSpike ? 92.0 : 25.0,
      ram_usage_percent: isSpike ? 93.0 : 38.0,
      disk_free_gb: 14.2
    }
  };
} else if (item.body && item.body.thermal_spike) {
  telemetry = {
    node_id: 'sbb-edge-thermal-spike-01',
    timestamp: new Date().toISOString(),
    hardware: {
      cpu_temp_celsius: 86.4,
      cpu_usage_percent: 95.0,
      ram_usage_percent: 94.2,
      disk_free_gb: 12.1
    }
  };
} else {
  telemetry = {
    node_id: 'sbb-edge-darwin-daemon',
    timestamp: new Date().toISOString(),
    hardware: {
      cpu_temp_celsius: 47.5,
      cpu_usage_percent: 18.2,
      ram_usage_percent: 42.0,
      disk_free_gb: 13.8
    }
  };
}

// Resolve dynamic platform threshold variables
const tempCritical = (typeof $vars !== 'undefined' && $vars.SBB_IOT_TEMP_CRITICAL_C) ? parseFloat($vars.SBB_IOT_TEMP_CRITICAL_C) : 82.0;
const tempWarning = (typeof $vars !== 'undefined' && $vars.SBB_IOT_TEMP_WARNING_C) ? parseFloat($vars.SBB_IOT_TEMP_WARNING_C) : 72.0;
const ramCritical = (typeof $vars !== 'undefined' && $vars.SBB_IOT_RAM_CRITICAL_PCT) ? parseFloat($vars.SBB_IOT_RAM_CRITICAL_PCT) : 92.0;

const hw = telemetry.hardware || {};
const alerts = [];

if ((hw.cpu_temp_celsius || 0) >= tempCritical) {
  alerts.push({
    severity: 'CRITICAL',
    code: 'ERR_THERMAL_RUNAWAY',
    message: `Critical CPU Temp: ${hw.cpu_temp_celsius}°C (Threshold: ${tempCritical}°C)`
  });
} else if ((hw.cpu_temp_celsius || 0) >= tempWarning) {
  alerts.push({
    severity: 'WARNING',
    code: 'WARN_THERMAL_ELEVATED',
    message: `Elevated CPU Temp: ${hw.cpu_temp_celsius}°C`
  });
}

if ((hw.ram_usage_percent || 0) >= ramCritical) {
  alerts.push({
    severity: 'CRITICAL',
    code: 'ERR_OOM_RISK',
    message: `RAM usage critical: ${hw.ram_usage_percent}% (Threshold: ${ramCritical}%)`
  });
}

const status = alerts.some(a => a.severity === 'CRITICAL') ? 'CRITICAL' : (alerts.length > 0 ? 'WARNING' : 'OPTIMAL');

const audit_event = {
  event_type: status === 'OPTIMAL' ? 'iot_telemetry_heartbeat' : 'iot_hardware_incident',
  source: 'sol-001-iot-telemetry-daemon',
  payload: {
    status: status,
    alert_count: alerts.length,
    alerts: alerts,
    hardware: {
      temp_c: hw.cpu_temp_celsius,
      cpu_pct: hw.cpu_usage_percent,
      ram_pct: hw.ram_usage_percent,
      disk_free_gb: hw.disk_free_gb
    }
  }
};

return [{
  json: {
    node_id: telemetry.node_id || 'sbb-edge-01',
    timestamp: telemetry.timestamp || new Date().toISOString(),
    status: status,
    alert_count: alerts.length,
    alerts: alerts,
    hardware_summary: audit_event.payload.hardware,
    audit_event: audit_event,
    action_taken: status === 'OPTIMAL' ? 'heartbeat_logged' : 'incident_dispatched',
    is_anomaly: status !== 'OPTIMAL'
  }
}];
